import _ from 'lodash';
import { useEffect, useState } from 'react';

export function OrderList({ orderIds }: { orderIds: string[] }) {
  return <ul>{orderIds.map((id) => <OrderRow key={id} id={id} />)}</ul>;
}

function OrderRow({ id }: { id: string }) {
  const [order, setOrder] = useState<any>(null);
  useEffect(() => {
    fetch(`/api/orders/${id}`).then((r) => r.json()).then(setOrder);
  }, [id]);
  if (!order) return <li>Loading...</li>;
  return <li>{_.startCase(order.customerName)} - {_.round(order.total, 2)}</li>;
}
