@app.get("/dashboard/summary")
def dashboard_summary(request):
    rng = request.args.get("range", "30d")
    key = f"dashboard-summary:{rng}"
    cached = redis.get(key)
    if cached:
        return json.loads(cached)
    summary = build_summary(org_id=request.user.org_id, range=rng)  # ~3 s of aggregate queries
    redis.set(key, json.dumps(summary), ex=300)
    return summary
