export function weekTotals(days: Day[], events: CalendarEvent[]) {
  // days is always the 7 days of the selected week
  return days.map((d) => ({
    date: d.date,
    hours: events
      .filter((e) => e.date === d.date)
      .reduce((sum, e) => sum + e.hours, 0),
  }));
}
